import { oporaSkillForDay, oporaSkillCards } from './anti-stress-skills-v5.js'

export const COURSE_ANTISTRESS_SKILLS_V6='hh-antistress-skills-v6-20261017'
export const OPORA54_SLIDE_MODEL='opora-fifteen-screens-v1'
export const OPORA54_PRE_SAVE_KEYS=Object.freeze([
  'welcome','baseline','pace','focus','aphorism','demo','prepare',
  'notice','act','rehearse','scenario','transfer','reflection','save',
])
export const OPORA54_RECEIPT_KEY='receipt'
export const OPORA54_LESSON_MINUTES=Object.freeze({target:[8,12],practice:[5,7]})
const RU=Object.freeze([["Добро пожаловать в день 1. Сегодня мы потренируемся: заметить первый возможный сигнал спешки и выбрать небольшой ответ. Не требуется быть в каком-то особом состоянии. Можно начать с небольшого шага.","Если вам удобно, отметьте: «Насколько сейчас вам доступно замечать ранние признаки напряжения?» Если удобно, выберите число от 0 до 10. Можно сразу перейти дальше без оценки. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, не тест.","Можно выбрать обычный темп, короткий вариант или только читать. Можно взять только вымышленный пример про сообщения. Вспоминать собственные неприятные эпизоды не нужно. Если что-либо станет неприятно, упражнение можно сразу остановить.","Сегодняшний фокус — отличать событие от первой реакции на него. Насколько вам близка именно эта задача? Можно выбрать общий вариант и не раскрывать личные данные.","Мысль дня: «Когда я замечаю спешку раньше, у меня появляется возможность выбрать паузу.» Как она вам? Можно не соглашаться, это не проверка правильности.","Сначала посмотрим на небольшой пример. Представьте: во время работы приходят четыре сообщения. Сами сообщения — событие; желание быстрее всё сделать — возможная реакция. Один вариант — закончить текущее дело, затем ответить. Что в нём было главным действием? Можно открыть объяснение ещё раз.","Перед практикой выберите удобный способ. Можно взять только вымышленный пример про сообщения. Вспоминать собственные неприятные эпизоды не нужно. Как вам лучше попробовать? Не нужно закрывать глаза или специально менять дыхание.","Первый маленький шаг. Прочитайте: «Пришли четыре сообщения». Какой ранний сигнал вы можете предположить у персонажа — спешка, рассеянность, усталость или пока неясно? Выберите один. После этого можно отметить, получилось ли попробовать. Если пока трудно — покажем подсказку.","Теперь основное действие. Соберите три карточки: «пришли сообщения» → «тороплюсь» → «ставлю одну задачу на паузу». Если хочется, произнесите про себя эту цепочку. Можно только прочитать. Можно попробовать ровно столько, сколько удобно. Что из этого было вам доступно?","Если хочется, попробуйте ещё один маленький раз. Теперь другая сцена: вы стоите в очереди и смотрите на время. Попробуйте без подсказки назвать возможный ранний сигнал и мягкий ответ. При необходимости откройте пример. Подсказка остаётся доступной, и можно отказаться от повторения.","Проверим идею на новой спокойной истории. Перед выходом появляется ещё одна просьба. Что помогает заметить напряжение раньше? Выберите тот ответ, который кажется наиболее бережным; при сомнении можно открыть пример.","Подумайте об обычном, безопасном моменте, когда это могло бы пригодиться. Если замечу, что спешу из-за нескольких сообщений, могу завершить одно дело и отложить следующее. Если не получается — попрошу больше времени. Можно сохранить только намерение — действовать сегодня необязательно.","Как прошёл опыт? Где было понятнее: заметить спешку или выбрать поддержку? Можно выбрать «подошло», «частично», «без изменений», «неприятно» или просто продолжить без ответа. Если хотите, ответьте на тот же вопрос, что в начале: «Насколько сейчас вам доступно замечать ранние признаки напряжения?»","Вот черновик вашей карточки дня: Возможный первый сигнал: спешка. Поддержка: маленькая пауза или уменьшение задачи. Мы покажем только ответы, которые вы действительно выбрали; ничего не будем додумывать. Можно исправить, сохранить или завершить без сохранения.","День 1 сохранён. Вы познакомились с навыком S1; в карточке указан только ваш настоящий опыт: пробовали, пробовали частично или решили не пробовать. Ваш темп подходит."],["Добро пожаловать в день 2. Сегодня мы потренируемся: найти нейтральный предмет и мягко вернуть к нему внимание. Не требуется быть в каком-то особом состоянии. Можно начать с небольшого шага.","Если вам удобно, отметьте: «Насколько сейчас вам доступно выбрать внешний предмет для внимания?» Если удобно, выберите число от 0 до 10. Можно сразу перейти дальше без оценки. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, не тест.","Можно выбрать обычный темп, короткий вариант или только читать. Выберите, на что удобно смотреть: на реальный предмет, окно или спокойную фотографию. Не нужно закрывать глаза или менять дыхание. Если что-либо станет неприятно, упражнение можно сразу остановить.","Сегодняшний фокус — ориентироваться во внешних деталях вместо требования немедленно успокоиться. Насколько вам близка именно эта задача? Можно выбрать общий вариант и не раскрывать личные данные.","Мысль дня: «Мне достаточно одной реальной детали вокруг, чтобы попробовать вернуться в настоящее.» Как она вам? Можно не соглашаться, это не проверка правильности.","Сначала посмотрим на небольшой пример. Посмотрите на рисунок комнаты. Можно выбрать окно, заметить прямоугольную раму и перевести взгляд на стол. Это пример переключения внимания, не обещание расслабления. Что в нём было главным действием? Можно открыть объяснение ещё раз.","Перед практикой выберите удобный способ. Выберите, на что удобно смотреть: на реальный предмет, окно или спокойную фотографию. Не нужно закрывать глаза или менять дыхание. Как вам лучше попробовать? Не нужно закрывать глаза или специально менять дыхание.","Первый маленький шаг. Найдите глазами один нейтральный цвет рядом или на рисунке. Можете мысленно назвать его: «серый», «зелёный», «синий». После этого можно отметить, получилось ли попробовать. Если пока трудно — покажем подсказку.","Теперь основное действие. Выберите два обычных предмета. Посмотрите на первый, затем на второй и снова на первый. Делайте это медленно, как удобно; можно прекратить в любой момент. Можно попробовать ровно столько, сколько удобно. Что из этого было вам доступно?","Если хочется, попробуйте ещё один маленький раз. Попробуйте выбрать другую пару предметов без подсказки. Получилось — хорошо; если не хочется повторять, можно только прочитать шаг. Подсказка остаётся доступной, и можно отказаться от повторения.","Проверим идею на новой спокойной истории. В очереди вы замечаете, что мысли всё время уходят к ожиданию. Что можно сделать без принуждения себя к спокойствию? Выберите тот ответ, который кажется наиболее бережным; при сомнении можно открыть пример.","Подумайте об обычном, безопасном моменте, когда это могло бы пригодиться. Если в обычном ожидании начинаю мысленно торопиться, могу на секунду посмотреть на цвет или форму предмета. Если не подходит — отдохну. Можно сохранить только намерение — действовать сегодня необязательно.","Как прошёл опыт? Было удобнее смотреть на один предмет или переключаться между двумя? Можно выбрать «подошло», «частично», «без изменений», «неприятно» или просто продолжить без ответа. Если хотите, ответьте на тот же вопрос, что в начале: «Насколько сейчас вам доступно выбрать внешний предмет для внимания?»","Вот черновик вашей карточки дня: Выбранный внешний ориентир: цвет, форма или предмет; запасной вариант — отдых. Мы покажем только ответы, которые вы действительно выбрали; ничего не будем додумывать. Можно исправить, сохранить или завершить без сохранения.","День 2 сохранён. Вы познакомились с навыком S2; в карточке указан только ваш настоящий опыт: пробовали, пробовали частично или решили не пробовать. Ваш темп подходит."],["Добро пожаловать в день 3. Сегодня мы потренируемся: попробовать самый мягкий доступный вариант движения, внешней опоры или отдыха. Не требуется быть в каком-то особом состоянии. Можно начать с небольшого шага.","Если вам удобно, отметьте: «Насколько сейчас вам доступно выбрать комфортную маленькую паузу?» Если удобно, выберите число от 0 до 10. Можно сразу перейти дальше без оценки. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, не тест.","Можно выбрать обычный темп, короткий вариант или только читать. Выберите один режим: сидя, стоя, без движения. Никаких потягиваний через боль и контроля дыхания. Если что-либо станет неприятно, упражнение можно сразу остановить.","Сегодняшний фокус — выбирать меру усилия без преодоления неприятных ощущений. Насколько вам близка именно эта задача? Можно выбрать общий вариант и не раскрывать личные данные.","Мысль дня: «Я могу уменьшить усилие и выбрать тот способ паузы, который мне подходит.» Как она вам? Можно не соглашаться, это не проверка правильности.","Сначала посмотрим на небольшой пример. Персонаж долго сидит за ноутбуком. Он мягко меняет положение кистей, затем позволяет им отдохнуть. Если движение не подходит, он просто переводит взгляд на внешний предмет. Что в нём было главным действием? Можно открыть объяснение ещё раз.","Перед практикой выберите удобный способ. Выберите один режим: сидя, стоя, без движения. Никаких потягиваний через боль и контроля дыхания. Как вам лучше попробовать? Не нужно закрывать глаза или специально менять дыхание.","Первый маленький шаг. Посмотрите, где вы сейчас находитесь. Если комфортно, отметьте устойчивую опору стула; если нет — просто выберите видимый предмет. После этого можно отметить, получилось ли попробовать. Если пока трудно — покажем подсказку.","Теперь основное действие. Если удобно, один раз слегка измените положение кистей или плеч, буквально на несколько сантиметров. Остановитесь и выберите: оставить положение, вернуться назад или отдохнуть. Можно попробовать ровно столько, сколько удобно. Что из этого было вам доступно?","Если хочется, попробуйте ещё один маленький раз. Сравните два варианта: маленькое движение и спокойный взгляд на предмет. Выберите, что было доступнее. Можно не повторять движение. Подсказка остаётся доступной, и можно отказаться от повторения.","Проверим идею на новой спокойной истории. После часа сидения за делом человеку хочется сделать короткую паузу. Что ему можно предложить? Выберите тот ответ, который кажется наиболее бережным; при сомнении можно открыть пример.","Подумайте об обычном, безопасном моменте, когда это могло бы пригодиться. Если замечу усталость после сидения, могу изменить положение рук или отдохнуть. Если неприятно — не буду выполнять движение. Можно сохранить только намерение — действовать сегодня необязательно.","Как прошёл опыт? Что оказалось удобнее: движение, внешний предмет или отдых? Можно выбрать «подошло», «частично», «без изменений», «неприятно» или просто продолжить без ответа. Если хотите, ответьте на тот же вопрос, что в начале: «Насколько сейчас вам доступно выбрать комфортную маленькую паузу?»","Вот черновик вашей карточки дня: Моя доступная пауза: микродвижение / внешний ориентир / отдых. Мы покажем только ответы, которые вы действительно выбрали; ничего не будем додумывать. Можно исправить, сохранить или завершить без сохранения.","День 3 сохранён. Вы познакомились с навыком S3; в карточке указан только ваш настоящий опыт: пробовали, пробовали частично или решили не пробовать. Ваш темп подходит."],["Добро пожаловать в день 4. Сегодня мы потренируемся: найти слово для мягкой эмоции в вымышленной ситуации и выбрать поддержку. Не требуется быть в каком-то особом состоянии. Можно начать с небольшого шага.","Если вам удобно, отметьте: «Насколько сейчас вам доступно спокойно назвать мягкое чувство в примере?» Если удобно, выберите число от 0 до 10. Можно сразу перейти дальше без оценки. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, не тест.","Можно выбрать обычный темп, короткий вариант или только читать. Останемся с безопасным вымышленным примером. Если он не подходит, можно смотреть на обычный предмет, не обращаясь к теме чувств. Если что-либо станет неприятно, упражнение можно сразу остановить.","Сегодняшний фокус — распознавать чувство без обязательного погружения в него. Насколько вам близка именно эта задача? Можно выбрать общий вариант и не раскрывать личные данные.","Мысль дня: «Я могу назвать чувство и всё равно выбирать, что делать дальше.» Как она вам? Можно не соглашаться, это не проверка правильности.","Сначала посмотрим на небольшой пример. Вымышленному человеку перенесли встречу. Он может почувствовать досаду, грусть или облегчение — по-разному. Он замечает возможное чувство и выбирает небольшую заботу о себе. Что в нём было главным действием? Можно открыть объяснение ещё раз.","Перед практикой выберите удобный способ. Останемся с безопасным вымышленным примером. Если он не подходит, можно смотреть на обычный предмет, не обращаясь к теме чувств. Как вам лучше попробовать? Не нужно закрывать глаза или специально менять дыхание.","Первый маленький шаг. Прочитайте: «Встречу перенесли на час позже». Какое мягкое чувство может возникнуть у персонажа: досада, грусть, облегчение или не знаю? После этого можно отметить, получилось ли попробовать. Если пока трудно — покажем подсказку.","Теперь основное действие. Попробуйте мысленно сказать про персонажа: «Он замечает досаду и может взять паузу». Затем направьте взгляд на две реальные детали вокруг. Не нужно менять свои чувства. Можно попробовать ровно столько, сколько удобно. Что из этого было вам доступно?","Если хочется, попробуйте ещё один маленький раз. В новой истории человек слегка разочаровался из-за изменения плана. Выберите одно возможное чувство и один мягкий ответ без подсказки или откройте помощь. Подсказка остаётся доступной, и можно отказаться от повторения.","Проверим идею на новой спокойной истории. Автобус опоздал, планы придётся чуть изменить. Как можно отнестись к возможной досаде? Выберите тот ответ, который кажется наиболее бережным; при сомнении можно открыть пример.","Подумайте об обычном, безопасном моменте, когда это могло бы пригодиться. Если появится лёгкая досада в обычном деле, могу назвать её и выбрать паузу. Если упражнение неприятно — остановлюсь. Можно сохранить только намерение — действовать сегодня необязательно.","Как прошёл опыт? Было проще выбрать слово чувства или способ поддержки? Можно выбрать «подошло», «частично», «без изменений», «неприятно» или просто продолжить без ответа. Если хотите, ответьте на тот же вопрос, что в начале: «Насколько сейчас вам доступно спокойно назвать мягкое чувство в примере?»","Вот черновик вашей карточки дня: Мягкое чувство в учебном случае и один безопасный способ заботы. Мы покажем только ответы, которые вы действительно выбрали; ничего не будем додумывать. Можно исправить, сохранить или завершить без сохранения.","День 4 сохранён. Вы познакомились с навыком S4; в карточке указан только ваш настоящий опыт: пробовали, пробовали частично или решили не пробовать. Ваш темп подходит."],["Добро пожаловать в день 5. Сегодня мы потренируемся: отделить известный факт от тревожной догадки и выбрать маленькое действие. Не требуется быть в каком-то особом состоянии. Можно начать с небольшого шага.","Если вам удобно, отметьте: «Насколько сейчас вам доступно отличить проверяемый факт от предположения?» Если удобно, выберите число от 0 до 10. Можно сразу перейти дальше без оценки. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, не тест.","Можно выбрать обычный темп, короткий вариант или только читать. Выберите нейтральный пример с перепиской или рабочей задачей. Свои реальные конфликты рассказывать не требуется. Если что-либо станет неприятно, упражнение можно сразу остановить.","Сегодняшний фокус — свободнее относиться к интерпретациям без принудительных позитивных мыслей. Насколько вам близка именно эта задача? Можно выбрать общий вариант и не раскрывать личные данные.","Мысль дня: «Не каждой тревожной мысли нужно верить или сразу следовать.» Как она вам? Можно не соглашаться, это не проверка правильности.","Сначала посмотрим на небольшой пример. Вымышленное сообщение осталось без ответа. Факт: ответа пока нет. Догадка: «Меня не ценят». Мы не знаем причины молчания. Что в нём было главным действием? Можно открыть объяснение ещё раз.","Перед практикой выберите удобный способ. Выберите нейтральный пример с перепиской или рабочей задачей. Свои реальные конфликты рассказывать не требуется. Как вам лучше попробовать? Не нужно закрывать глаза или специально менять дыхание.","Первый маленький шаг. Прочитайте два предложения: «Ответ пока не пришёл» и «Меня игнорируют». Какое из них точно известно, а какое является предположением? После этого можно отметить, получилось ли попробовать. Если пока трудно — покажем подсказку.","Теперь основное действие. Переместите четыре короткие фразы в две колонки «Факт» и «Предположение». Затем попробуйте фразу «У меня появилась мысль, что…». Можно попробовать ровно столько, сколько удобно. Что из этого было вам доступно?","Если хочется, попробуйте ещё один маленький раз. Теперь коллега написал короткое «Ок». Что известно, а что мы додумываем? Попробуйте различить самостоятельно; подсказка доступна. Подсказка остаётся доступной, и можно отказаться от повторения.","Проверим идею на новой спокойной истории. Пришёл краткий ответ от знакомого. Как не делать поспешный вывод? Выберите тот ответ, который кажется наиболее бережным; при сомнении можно открыть пример.","Подумайте об обычном, безопасном моменте, когда это могло бы пригодиться. Если замечу мысль «со мной что-то не так», могу отделить факт от догадки и сделать один посильный шаг или паузу. Можно сохранить только намерение — действовать сегодня необязательно.","Как прошёл опыт? Сложнее было найти факт или не соглашаться сразу с догадкой? Можно выбрать «подошло», «частично», «без изменений», «неприятно» или просто продолжить без ответа. Если хотите, ответьте на тот же вопрос, что в начале: «Насколько сейчас вам доступно отличить проверяемый факт от предположения?»","Вот черновик вашей карточки дня: Карточка: факт → предположение → доступный следующий шаг. Мы покажем только ответы, которые вы действительно выбрали; ничего не будем додумывать. Можно исправить, сохранить или завершить без сохранения.","День 5 сохранён. Вы познакомились с навыком S5; в карточке указан только ваш настоящий опыт: пробовали, пробовали частично или решили не пробовать. Ваш темп подходит."],["Добро пожаловать в день 6. Сегодня мы потренируемся: составить простую фразу границы и просьбу без обязательного реального разговора. Не требуется быть в каком-то особом состоянии. Можно начать с небольшого шага.","Если вам удобно, отметьте: «Насколько сейчас вам доступно придумать спокойную фразу «мне нужна пауза»?» Если удобно, выберите число от 0 до 10. Можно сразу перейти дальше без оценки. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, не тест.","Можно выбрать обычный темп, короткий вариант или только читать. Сегодня только учебный диалог. Не нужно вспоминать конфликт или отправлять кому-либо сообщение. Если что-либо станет неприятно, упражнение можно сразу остановить.","Сегодняшний фокус — коротко и уважительно сообщать о своём ресурсе. Насколько вам близка именно эта задача? Можно выбрать общий вариант и не раскрывать личные данные.","Мысль дня: «Я могу уважать другого человека и при этом беречь своё время и силы.» Как она вам? Можно не соглашаться, это не проверка правильности.","Сначала посмотрим на небольшой пример. Вымышленный коллега просит дополнительную задачу. Ответ персонажа: «Сейчас не могу. Смогу вернуться завтра». Эта фраза обозначает предел без обвинения. Что в нём было главным действием? Можно открыть объяснение ещё раз.","Перед практикой выберите удобный способ. Сегодня только учебный диалог. Не нужно вспоминать конфликт или отправлять кому-либо сообщение. Как вам лучше попробовать? Не нужно закрывать глаза или специально менять дыхание.","Первый маленький шаг. В просьбе «Поможешь сегодня вечером?» что человеку может понадобиться: дополнительное время, отдых, помощь или пока неясно? После этого можно отметить, получилось ли попробовать. Если пока трудно — покажем подсказку.","Теперь основное действие. Соберите из коротких блоков фразу: «Спасибо за просьбу» + «Сейчас не могу» + «Могу позже / не смогу». Произнесите про себя или просто прочитайте. Можно попробовать ровно столько, сколько удобно. Что из этого было вам доступно?","Если хочется, попробуйте ещё один маленький раз. Теперь другая нейтральная просьба: «Давайте созвонимся прямо сейчас». Попробуйте выбрать короткий ответ без подсказки или откройте пример. Подсказка остаётся доступной, и можно отказаться от повторения.","Проверим идею на новой спокойной истории. Знакомый приглашает встретиться, когда нет свободного времени. Как ответить без длинного оправдания? Выберите тот ответ, который кажется наиболее бережным; при сомнении можно открыть пример.","Подумайте об обычном, безопасном моменте, когда это могло бы пригодиться. Если появится лишняя просьба в безопасной ситуации, могу сказать «мне нужна пауза» или «отвечу позже». Если не безопасно — выберу помощь. Можно сохранить только намерение — действовать сегодня необязательно.","Как прошёл опыт? Какая фраза ощущалась более правдоподобной? Можно выбрать «подошло», «частично», «без изменений», «неприятно» или просто продолжить без ответа. Если хотите, ответьте на тот же вопрос, что в начале: «Насколько сейчас вам доступно придумать спокойную фразу «мне нужна пауза»?»","Вот черновик вашей карточки дня: Моя возможная короткая граница и резервная просьба о помощи. Мы покажем только ответы, которые вы действительно выбрали; ничего не будем додумывать. Можно исправить, сохранить или завершить без сохранения.","День 6 сохранён. Вы познакомились с навыком S6; в карточке указан только ваш настоящий опыт: пробовали, пробовали частично или решили не пробовать. Ваш темп подходит."],["Добро пожаловать в день 7. Сегодня мы потренируемся: собрать из нескольких знакомых способов короткую реалистичную последовательность. Не требуется быть в каком-то особом состоянии. Можно начать с небольшого шага.","Если вам удобно, отметьте: «Насколько сейчас вам доступно выбрать одну знакомую опору для обычного дня?» Если удобно, выберите число от 0 до 10. Можно сразу перейти дальше без оценки. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, не тест.","Можно выбрать обычный темп, короткий вариант или только читать. Посмотрите только на те способы, с которыми вы знакомились раньше. Не нужно выбирать их все. Если ни один не подходит, допустим нейтральный отдых. Если что-либо станет неприятно, упражнение можно сразу остановить.","Сегодняшний фокус — использовать доступное, а не все навыки одновременно. Насколько вам близка именно эта задача? Можно выбрать общий вариант и не раскрывать личные данные.","Мысль дня: «Мне достаточно одного маленького доступного шага, чтобы начать поддерживать себя.» Как она вам? Можно не соглашаться, это не проверка правильности.","Сначала посмотрим на небольшой пример. Персонаж устал после дел. Он замечает усталость, выбирает пятиминутный отдых и оставляет запасной вариант — попросить помощи. Это не экзамен на семь навыков. Что в нём было главным действием? Можно открыть объяснение ещё раз.","Перед практикой выберите удобный способ. Посмотрите только на те способы, с которыми вы знакомились раньше. Не нужно выбирать их все. Если ни один не подходит, допустим нейтральный отдых. Как вам лучше попробовать? Не нужно закрывать глаза или специально менять дыхание.","Первый маленький шаг. В сцене «вечером приходит новая просьба» найдите один возможный ранний сигнал: усталость, спешка или отвлечение. Можно выбрать «не знаю». После этого можно отметить, получилось ли попробовать. Если пока трудно — покажем подсказку.","Теперь основное действие. Соберите карточку: «заметил усталость» → «выбираю паузу» → «если не выходит, попрошу больше времени». Оставьте только то, что действительно кажется доступным. Можно попробовать ровно столько, сколько удобно. Что из этого было вам доступно?","Если хочется, попробуйте ещё один маленький раз. В другой безопасной сцене с утренними делами попробуйте собрать такую же маленькую цепочку с другим сигналом. Можно открыть подсказку. Подсказка остаётся доступной, и можно отказаться от повторения.","Проверим идею на новой спокойной истории. После насыщенного дня добавилась домашняя просьба. Как выбрать подходящую опору? Выберите тот ответ, который кажется наиболее бережным; при сомнении можно открыть пример.","Подумайте об обычном, безопасном моменте, когда это могло бы пригодиться. Если замечу ранний сигнал в обычном деле, могу выбрать одну опору; если она не подходит — отдохну или попрошу помощи. Можно сохранить только намерение — действовать сегодня необязательно.","Как прошёл опыт? Какие два шага действительно реалистичны, а что лучше убрать? Можно выбрать «подошло», «частично», «без изменений», «неприятно» или просто продолжить без ответа. Если хотите, ответьте на тот же вопрос, что в начале: «Насколько сейчас вам доступно выбрать одну знакомую опору для обычного дня?»","Вот черновик вашей карточки дня: Первая личная карта ОПОРА: сигнал → одна поддержка → запасной вариант. Мы покажем только ответы, которые вы действительно выбрали; ничего не будем додумывать. Можно исправить, сохранить или завершить без сохранения.","День 7 сохранён. Вы познакомились с навыком S7; в карточке указан только ваш настоящий опыт: пробовали, пробовали частично или решили не пробовать. Ваш темп подходит."],["День 8. Замечаю стресс до перегрузки. Мы продолжим знакомый навык S1, но на новых спокойных примерах. Сегодня попробуем вспомнить ранний сигнал и найти поддержку в новой повседневной ситуации. Вы сами выбираете темп.","Если удобно, отметьте: «Насколько сейчас вам доступно замечать ранний сигнал без подробной инструкции?» по шкале 0–10 или пропустите. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, а не отметка об успехе.","Как комфортнее заниматься: попробовать сначала без подсказки, с подсказкой или только читать? Можно работать только с нейтральными историями про список дел или уведомления. Личные сложные события не нужны. Можно прекратить в любой момент.","Сегодняшняя задача: распознавать первые изменения при обычной спешке с меньшим количеством подсказок. Она может быть общей. Не нужно рассказывать личный эпизод или подбирать диагноз.","Мысль дня: «Чем раньше я замечаю свою спешку, тем больше возможных маленьких решений.» Как она вам? Даже если не согласны, упражнение можно попробовать в удобном виде.","Посмотрите один пример: Вымышленный человек читает сообщение, пока заканчивает дело. Он замечает, что уже переключил внимание три раза, и решает сначала завершить одну маленькую задачу. Было ли понятно, какое маленькое действие выбрал человек?","Подготовимся без спешки. Можно работать только с нейтральными историями про список дел или уведомления. Личные сложные события не нужны. Какой вариант вам подходит прямо сейчас?","Начните с небольшой попытки заметить. В истории «три задачи одновременно» выберите самый ранний возможный знак: начал метаться между делами, почувствовал усталость или пока неясно. После этого вы сможете сказать, что реально произошло, без оценки «правильно/неправильно».","Теперь главное действие, в вашем темпе. Рассмотрите два новых примера. Для каждого соберите «событие → ранний сигнал → один маленький ответ», не глядя на готовую подсказку. Можно замедлиться и выбрать только один пример. Можно остановиться раньше или только прочитать.","Если хочется повторить, попробуйте небольшой новый вариант. Новая история: очередь движется медленнее ожидаемого. Мысленно назовите сигнал и одну поддержку самостоятельно или с подсказкой. Подсказку можно открыть в любой момент.","Новый спокойный пример: За несколько минут до выхода появилась ещё одна бытовая просьба. Как применить знакомую цепочку? Выберите наиболее бережный вариант, или откройте пояснение.","Для обычного безопасного момента можно подготовить небольшое правило: Если при новых просьбах замечу, что начинаю спешить, сначала определю один посильный шаг. Если трудно — попрошу дополнительное время. Составление плана не обязывает делать это сегодня.","Что вы заметили? Было ли проще назвать сигнал спустя неделю? Нужна ли краткая подсказка? Можно выбрать «подошло», «частично», «без изменений» или «неприятно». Если хочется, ещё раз оцените: «Насколько сейчас вам доступно замечать ранний сигнал без подробной инструкции?» (0–10).","В вашей карточке отмечено только то, что вы действительно выбрали: Вторая учебная попытка S1: возможный сигнал, маленький ответ и использованная подсказка. Можно исправить запись или оставить без сохранения.","Занятие 8/14 сохранено. Вы познакомились или снова попробовали S1. Если пользовались подсказкой, мы не объявляем навыка автоматически самостоятельным. Ваш выбор сохраняется без оценок личности."],["День 9. Самостоятельно возвращаю внимание. Мы продолжим знакомый навык S2, но на новых спокойных примерах. Сегодня попробуем выбирать нейтральный внешний ориентир в новой бытовой ситуации ожидания. Вы сами выбираете темп.","Если удобно, отметьте: «Насколько сейчас вам доступно самостоятельно выбрать внешний ориентир?» по шкале 0–10 или пропустите. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, а не отметка об успехе.","Как комфортнее заниматься: попробовать сначала без подсказки, с подсказкой или только читать? Выберите действительный предмет, спокойную фотографию или только текстовый пример. Глаза можно оставить открытыми. Можно прекратить в любой момент.","Сегодняшняя задача: возвращать фокус внимания без требования немедленно успокоиться. Она может быть общей. Не нужно рассказывать личный эпизод или подбирать диагноз.","Мысль дня: «Я могу возвращать внимание к реальной детали, даже если мысли продолжают приходить.» Как она вам? Даже если не согласны, упражнение можно попробовать в удобном виде.","Посмотрите один пример: Вымышленный персонаж ждёт ответа на электронное письмо. Он замечает край окна и форму чашки; его мысли могут оставаться беспокойными, но выбор посмотреть вокруг остаётся доступен. Было ли понятно, какое маленькое действие выбрал человек?","Подготовимся без спешки. Выберите действительный предмет, спокойную фотографию или только текстовый пример. Глаза можно оставить открытыми. Какой вариант вам подходит прямо сейчас?","Начните с небольшой попытки заметить. Без готового списка найдите вокруг один предмет и мысленно назовите его форму. Если сложно, откройте подсказку с цветом или линией. После этого вы сможете сказать, что реально произошло, без оценки «правильно/неправильно».","Теперь главное действие, в вашем темпе. Посмотрите на выбранный предмет, затем на второй. Спокойно вернитесь к первому. Если хочется, назовите цвет и форму; если не хочется — просто завершите наблюдение. Можно остановиться раньше или только прочитать.","Если хочется повторить, попробуйте небольшой новый вариант. Теперь выберите другую пару предметов без подсказки. Если кажется сложным, оставьте одну деталь. Не нужно считать секунды или контролировать дыхание. Подсказку можно открыть в любой момент.","Новый спокойный пример: В магазине нужно немного подождать. Куда человек может по своей воле направить взгляд? Выберите наиболее бережный вариант, или откройте пояснение.","Для обычного безопасного момента можно подготовить небольшое правило: Если в обычной очереди мысли уводят меня в ожидание, я могу назвать форму предмета вокруг; если не подходит — отдохну. Составление плана не обязывает делать это сегодня.","Что вы заметили? Удалось ли выбрать ориентир без подсказки? Что сработало удобнее? Можно выбрать «подошло», «частично», «без изменений» или «неприятно». Если хочется, ещё раз оцените: «Насколько сейчас вам доступно самостоятельно выбрать внешний ориентир?» (0–10).","В вашей карточке отмечено только то, что вы действительно выбрали: Вторая попытка S2: один внешний ориентир и честная отметка о подсказке. Можно исправить запись или оставить без сохранения.","Занятие 9/14 сохранено. Вы познакомились или снова попробовали S2. Если пользовались подсказкой, мы не объявляем навыка автоматически самостоятельным. Ваш выбор сохраняется без оценок личности."],["День 10. Подбираю паузу под нагрузку. Мы продолжим знакомый навык S3, но на новых спокойных примерах. Сегодня попробуем отличать избыток дел от усталости и выбирать доступную поддержку без самодиагностики. Вы сами выбираете темп.","Если удобно, отметьте: «Насколько сейчас вам доступно выбрать вид поддержки для обычной нагрузки?» по шкале 0–10 или пропустите. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, а не отметка об успехе.","Как комфортнее заниматься: попробовать сначала без подсказки, с подсказкой или только читать? Можно рассмотреть только вымышленные примеры. Если движение неприятно, оставайтесь с внешним предметом или отдыхом. Можно прекратить в любой момент.","Сегодняшняя задача: выбирать между уменьшением требований, отдыхом и внешней опорой. Она может быть общей. Не нужно рассказывать личный эпизод или подбирать диагноз.","Мысль дня: «Разным дням нужна разная поддержка: иногда пауза, иногда уменьшение требований.» Как она вам? Даже если не согласны, упражнение можно попробовать в удобном виде.","Посмотрите один пример: Персонаж А получает пять новых задач — решает отложить второстепенную. Персонаж Б устал после работы — выбирает отдых. Оба могут выбрать по-другому в своей реальной ситуации. Было ли понятно, какое маленькое действие выбрал человек?","Подготовимся без спешки. Можно рассмотреть только вымышленные примеры. Если движение неприятно, оставайтесь с внешним предметом или отдыхом. Какой вариант вам подходит прямо сейчас?","Начните с небольшой попытки заметить. Посмотрите на две истории: «очень много просьб» и «мало сил после дела». Подберите для каждой возможную поддержку, не оценивая своё здоровье. После этого вы сможете сказать, что реально произошло, без оценки «правильно/неправильно».","Теперь главное действие, в вашем темпе. Соберите два небольших правила для персонажей. При желании мягко измените положение кистей или посмотрите на внешний предмет на 20–30 секунд. Никакого усилия через неприятность. Можно остановиться раньше или только прочитать.","Если хочется повторить, попробуйте небольшой новый вариант. Третья история: после длинного разговора хочется тишины. Подберите вариант без готового ответа; откройте подсказку, если требуется. Подсказку можно открыть в любой момент.","Новый спокойный пример: В конце рабочего дня добавилась ещё одна задача. Что может быть подходящим первым ответом? Выберите наиболее бережный вариант, или откройте пояснение.","Для обычного безопасного момента можно подготовить небольшое правило: Если задач слишком много, могу упростить одно требование; если сил мало — выбрать отдых; если неясно — нейтральный предмет. Составление плана не обязывает делать это сегодня.","Что вы заметили? Что оказалось понятнее: уменьшить задачи или выбрать восстановление? Можно выбрать «подошло», «частично», «без изменений» или «неприятно». Если хочется, ещё раз оцените: «Насколько сейчас вам доступно выбрать вид поддержки для обычной нагрузки?» (0–10).","В вашей карточке отмечено только то, что вы действительно выбрали: Вторая попытка S3: доступное решение для нагрузки и отдельный вариант для усталости. Можно исправить запись или оставить без сохранения.","Занятие 10/14 сохранено. Вы познакомились или снова попробовали S3. Если пользовались подсказкой, мы не объявляем навыка автоматически самостоятельным. Ваш выбор сохраняется без оценок личности."],["День 11. Сохраняю выбор рядом с чувствами. Мы продолжим знакомый навык S4, но на новых спокойных примерах. Сегодня попробуем заметить мягкое чувство персонажа и самостоятельно подобрать бережный вариант поддержки. Вы сами выбираете темп.","Если удобно, отметьте: «Насколько сейчас вам доступно назвать мягкое чувство и выбрать паузу?» по шкале 0–10 или пропустите. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, а не отметка об успехе.","Как комфортнее заниматься: попробовать сначала без подсказки, с подсказкой или только читать? Используем только очень мягкий вымышленный случай или нейтральную фотографию. При неприятных ощущениях переходите к отдыху. Можно прекратить в любой момент.","Сегодняшняя задача: дозированно переключать внимание между словом чувства и внешним ориентиром. Она может быть общей. Не нужно рассказывать личный эпизод или подбирать диагноз.","Мысль дня: «Чувство может быть рядом со мной, но оно не обязано управлять каждым моим шагом.» Как она вам? Даже если не согласны, упражнение можно попробовать в удобном виде.","Посмотрите один пример: Персонажу немного изменили планы. Он может чувствовать досаду и всё же выбрать перерыв. Сильных чувств не вызываем, а внешняя опора остаётся доступной. Было ли понятно, какое маленькое действие выбрал человек?","Подготовимся без спешки. Используем только очень мягкий вымышленный случай или нейтральную фотографию. При неприятных ощущениях переходите к отдыху. Какой вариант вам подходит прямо сейчас?","Начните с небольшой попытки заметить. Прочитайте: «Встречу сдвинули на полчаса». Выберите, что мог бы заметить персонаж: досаду, удивление, облегчение или не знаю. После этого вы сможете сказать, что реально произошло, без оценки «правильно/неправильно».","Теперь главное действие, в вашем темпе. Если удобно, прочитайте: «Он замечает досаду». Посмотрите на два реальных предмета рядом. Затем выберите вариант заботы: отдых, короткая поддерживающая фраза или попросить время. Можно остановиться раньше или только прочитать.","Если хочется повторить, попробуйте небольшой новый вариант. Новый пример: небольшая задержка по дороге. Назовите возможное чувство персонажа и мягкий ответ без подсказки. Если не подходит — прекратите. Подсказку можно открыть в любой момент.","Новый спокойный пример: Автобус опоздал, и нужно изменить неважный план. Как можно обойтись с досадой? Выберите наиболее бережный вариант, или откройте пояснение.","Для обычного безопасного момента можно подготовить небольшое правило: Если в безопасном случае замечу небольшую досаду, могу назвать её и вернуться к внешней опоре. Если неприятно — остановлю упражнение. Составление плана не обязывает делать это сегодня.","Что вы заметили? Хотелось ли уменьшить контакт с эмоцией? Что подошло для внешней опоры? Можно выбрать «подошло», «частично», «без изменений» или «неприятно». Если хочется, ещё раз оцените: «Насколько сейчас вам доступно назвать мягкое чувство и выбрать паузу?» (0–10).","В вашей карточке отмечено только то, что вы действительно выбрали: Вторая попытка S4: слово чувства в учебном сюжете и выбранная поддержка. Можно исправить запись или оставить без сохранения.","Занятие 11/14 сохранено. Вы познакомились или снова попробовали S4. Если пользовались подсказкой, мы не объявляем навыка автоматически самостоятельным. Ваш выбор сохраняется без оценок личности."],["День 12. Выбираю действие при тревожной мысли. Мы продолжим знакомый навык S5, но на новых спокойных примерах. Сегодня попробуем отделять догадку от факта и выбирать небольшой шаг согласно важному качеству поведения. Вы сами выбираете темп.","Если удобно, отметьте: «Насколько сейчас вам доступно выбрать шаг, не следуя каждой тревожной мысли?» по шкале 0–10 или пропустите. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, а не отметка об успехе.","Как комфортнее заниматься: попробовать сначала без подсказки, с подсказкой или только читать? Выберите вымышленную переписку. Личные конфликты, чувство вины или травматические воспоминания описывать не требуется. Можно прекратить в любой момент.","Сегодняшняя задача: замечать мысль без обязательного спора с ней и действовать по ценности. Она может быть общей. Не нужно рассказывать личный эпизод или подбирать диагноз.","Мысль дня: «Я могу заметить тревожную мысль и всё-таки сделать небольшой выбор по своим ценностям.» Как она вам? Даже если не согласны, упражнение можно попробовать в удобном виде.","Посмотрите один пример: Коллега пишет только «Ок». Герой думает «он недоволен», но знает лишь текст ответа. Он выбирает ясность и решает спокойно уточнить позже. Было ли понятно, какое маленькое действие выбрал человек?","Подготовимся без спешки. Выберите вымышленную переписку. Личные конфликты, чувство вины или травматические воспоминания описывать не требуется. Какой вариант вам подходит прямо сейчас?","Начните с небольшой попытки заметить. Разделите в сцене две фразы: «получен ответ “Ок”» и «человек мной недоволен». Какая фраза — наблюдение? После этого вы сможете сказать, что реально произошло, без оценки «правильно/неправильно».","Теперь главное действие, в вашем темпе. Соберите последовательность: факт → догадка → ценность «ясность/уважение/забота» → маленький шаг. Выберите свой вариант для персонажа. Можно просто прочитать. Можно остановиться раньше или только прочитать.","Если хочется повторить, попробуйте небольшой новый вариант. Новая ситуация: подтверждение встречи задерживается. Попробуйте без подсказки назвать мысль как мысль, важное качество ответа и посильный шаг. Подсказку можно открыть в любой момент.","Новый спокойный пример: На приглашение пока не ответили. Как сохранить уважение к себе и другому без обязательного оптимизма? Выберите наиболее бережный вариант, или откройте пояснение.","Для обычного безопасного момента можно подготовить небольшое правило: Если появляется повторяющаяся тревожная догадка, могу отделить её от факта и выбрать маленькое действие по ценности или паузу. Составление плана не обязывает делать это сегодня.","Что вы заметили? Было ли труднее заметить мысль или выбрать действие по ценности? Можно выбрать «подошло», «частично», «без изменений» или «неприятно». Если хочется, ещё раз оцените: «Насколько сейчас вам доступно выбрать шаг, не следуя каждой тревожной мысли?» (0–10).","В вашей карточке отмечено только то, что вы действительно выбрали: Вторая попытка S5: факт, догадка, выбранная ценность и возможный шаг. Можно исправить запись или оставить без сохранения.","Занятие 12/14 сохранено. Вы познакомились или снова попробовали S5. Если пользовались подсказкой, мы не объявляем навыка автоматически самостоятельным. Ваш выбор сохраняется без оценок личности."],["День 13. Повторяю границу в диалоге. Мы продолжим знакомый навык S6, но на новых спокойных примерах. Сегодня попробуем отрепетировать короткую границу при уточняющем или повторном запросе. Вы сами выбираете темп.","Если удобно, отметьте: «Насколько сейчас вам доступно подготовить короткий ответ на повторную просьбу?» по шкале 0–10 или пропустите. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, а не отметка об успехе.","Как комфортнее заниматься: попробовать сначала без подсказки, с подсказкой или только читать? Диалог остаётся вымышленным. Выберите чтение, сбор фразы или мысленную репетицию. Не пишите реальным людям. Можно прекратить в любой момент.","Сегодняшняя задача: спокойно обозначать доступность времени без обязательной конфронтации. Она может быть общей. Не нужно рассказывать личный эпизод или подбирать диагноз.","Мысль дня: «Я могу повторить свою границу спокойно, даже если меня попросили ещё раз.» Как она вам? Даже если не согласны, упражнение можно попробовать в удобном виде.","Посмотрите один пример: Персонажа просят помочь сегодня. Он говорит: «Сегодня не смогу». Собеседник уточняет: «А через час?» Персонаж спокойно повторяет: «Сегодня не получится». Было ли понятно, какое маленькое действие выбрал человек?","Подготовимся без спешки. Диалог остаётся вымышленным. Выберите чтение, сбор фразы или мысленную репетицию. Не пишите реальным людям. Какой вариант вам подходит прямо сейчас?","Начните с небольшой попытки заметить. В истории «можешь помочь вечером?» определите границу персонажа: время, силы, желание отдохнуть или неясно. После этого вы сможете сказать, что реально произошло, без оценки «правильно/неправильно».","Теперь главное действие, в вашем темпе. Соберите ответ «Спасибо, сегодня не смогу». Затем откройте реакцию персонажа: «хорошо / почему / а завтра?» Выберите спокойную короткую реплику в ответ. Можно остановиться раньше или только прочитать.","Если хочется повторить, попробуйте небольшой новый вариант. Теперь новая просьба: «Можно созвониться прямо сейчас?» Попробуйте ответить без подсказки, затем выбрать вторую реплику, если просьбу повторят. Подсказку можно открыть в любой момент.","Новый спокойный пример: Встреча не подходит по времени, но приглашение повторяют. Как остаться уважительным и сохранить границу? Выберите наиболее бережный вариант, или откройте пояснение.","Для обычного безопасного момента можно подготовить небольшое правило: Если в безопасной ситуации просьбу повторят, могу коротко повторить свою границу. Если небезопасно — не буду тренироваться вживую. Составление плана не обязывает делать это сегодня.","Что вы заметили? Какая повторная фраза звучала естественно, а какая нет? Можно выбрать «подошло», «частично», «без изменений» или «неприятно». Если хочется, ещё раз оцените: «Насколько сейчас вам доступно подготовить короткий ответ на повторную просьбу?» (0–10).","В вашей карточке отмечено только то, что вы действительно выбрали: Вторая попытка S6: фраза границы, вариант ответить повторно и безопасный резерв. Можно исправить запись или оставить без сохранения.","Занятие 13/14 сохранено. Вы познакомились или снова попробовали S6. Если пользовались подсказкой, мы не объявляем навыка автоматически самостоятельным. Ваш выбор сохраняется без оценок личности."],["День 14. Мой личный план ОПОРА. Мы продолжим знакомый навык S7, но на новых спокойных примерах. Сегодня попробуем выбрать один-два реально доступных навыка и резерв для нового обычного контекста. Вы сами выбираете темп.","Если удобно, отметьте: «Насколько сейчас вам доступно выбрать знакомую опору для обычной ситуации?» по шкале 0–10 или пропустите. Ноль — сейчас почти недоступно, десять — доступно. Это наблюдение, а не отметка об успехе.","Как комфортнее заниматься: попробовать сначала без подсказки, с подсказкой или только читать? Выберите безопасную вымышленную ситуацию или свой обычный пример без болезненных деталей. Посмотрите на навыки, которые вы действительно пробовали. Можно прекратить в любой момент.","Сегодняшняя задача: не заучивать семь правил, а самостоятельно подбирать один посильный способ. Она может быть общей. Не нужно рассказывать личный эпизод или подбирать диагноз.","Мысль дня: «Мне не нужно применять всё сразу: один подходящий шаг и запасной вариант уже полезны.» Как она вам? Даже если не согласны, упражнение можно попробовать в удобном виде.","Посмотрите один пример: Вечером неожиданно появляется небольшое дело. Герой замечает усталость, выбирает уменьшить второстепенную задачу и оставляет резерв — отдохнуть или попросить время. Было ли понятно, какое маленькое действие выбрал человек?","Подготовимся без спешки. Выберите безопасную вымышленную ситуацию или свой обычный пример без болезненных деталей. Посмотрите на навыки, которые вы действительно пробовали. Какой вариант вам подходит прямо сейчас?","Начните с небольшой попытки заметить. В новой истории «сразу несколько сообщений утром» выберите возможный первый сигнал: спешка, рассеянность, усталость или не знаю. После этого вы сможете сказать, что реально произошло, без оценки «правильно/неправильно».","Теперь главное действие, в вашем темпе. Соберите карточку: сигнал → одна доступная опора → небольшой следующий шаг → запас. Можно выбрать внешний предмет, отдых, факт/догадку, фразу границы или помощь. Можно остановиться раньше или только прочитать.","Если хочется повторить, попробуйте небольшой новый вариант. Перенесите свою карточку на новый пример «планы меняются за час до выхода». Попробуйте выбрать одну подходящую поддержку без подсказки, если удобно. Подсказку можно открыть в любой момент.","Новый спокойный пример: В течение обычного дня появляется дополнительная просьба. Что лучше всего соответствует вашей настоящей доступности? Выберите наиболее бережный вариант, или откройте пояснение.","Для обычного безопасного момента можно подготовить небольшое правило: Если замечу свой ранний сигнал в безопасном обычном деле, могу использовать одну доступную опору; если она не подходит — выберу отдых или помощь. Составление плана не обязывает делать это сегодня.","Что вы заметили? Какие из семи навыков вы действительно пробовали, а какие пока только изучили? Что можно упростить? Можно выбрать «подошло», «частично», «без изменений» или «неприятно». Если хочется, ещё раз оцените: «Насколько сейчас вам доступно выбрать знакомую опору для обычной ситуации?» (0–10).","В вашей карточке отмечено только то, что вы действительно выбрали: Финальная карта ОПОРА: реальный сигнал, доступная опора, маленький шаг, запас; честная история попыток. Можно исправить запись или оставить без сохранения.","Занятие 14/14 сохранено. Вы познакомились или снова попробовали S7. Если пользовались подсказкой, мы не объявляем навыка автоматически самостоятельным. Ваш выбор сохраняется без оценок личности."]])
const QUOTES=Object.freeze([{"ru":"Когда я замечаю спешку раньше, у меня появляется возможность выбрать паузу.","en":"Noticing my hurry early can give me a chance to pause.","ruNeutral":"Мне не обязательно замечать всё сразу. Я могу начать с одного сигнала.","enNeutral":"I do not need to notice everything. One signal is enough to begin."},{"ru":"Мне достаточно одной реальной детали вокруг, чтобы попробовать вернуться в настоящее.","en":"One ordinary detail around me can help me return my attention to the present.","ruNeutral":"Я могу просто посмотреть вокруг и ничего не менять в своём состоянии.","enNeutral":"I can simply look around without trying to change how I feel."},{"ru":"Я могу уменьшить усилие и выбрать тот способ паузы, который мне подходит.","en":"I can ease my effort and choose the kind of pause that suits me.","ruNeutral":"Даже без движения я могу сделать паузу и посмотреть на нейтральный предмет.","enNeutral":"I can take a pause without moving, simply by looking at an ordinary object."},{"ru":"Я могу назвать чувство и всё равно выбирать, что делать дальше.","en":"I can name a feeling and still choose what I do next.","ruNeutral":"Мне не нужно переживать сильные чувства ради упражнения.","enNeutral":"I do not need to experience intense feelings to try this exercise."},{"ru":"Не каждой тревожной мысли нужно верить или сразу следовать.","en":"I do not have to believe or follow every worrying thought.","ruNeutral":"Я могу просто заметить: «Это мысль». Мне не нужно себя переубеждать.","enNeutral":"I can simply notice: “This is a thought.” I do not have to argue with it."},{"ru":"Я могу уважать другого человека и при этом беречь своё время и силы.","en":"I can respect others while making room for my time and energy.","ruNeutral":"Я могу только подготовить фразу; реальный разговор необязателен.","enNeutral":"I can prepare a phrase without having to say it to anyone."},{"ru":"Мне достаточно одного маленького доступного шага, чтобы начать поддерживать себя.","en":"One realistic small step can be enough to begin supporting myself.","ruNeutral":"Мой план может быть совсем коротким, а отдых — подходящим вариантом.","enNeutral":"My plan can be short, and rest can be a suitable option."},{"ru":"Чем раньше я замечаю свою спешку, тем больше возможных маленьких решений.","en":"Noticing my hurry sooner may leave me more small choices.","ruNeutral":"Мне достаточно попробовать заметить одно изменение, с подсказкой или без.","enNeutral":"I can try to notice one change, with a hint or without."},{"ru":"Я могу возвращать внимание к реальной детали, даже если мысли продолжают приходить.","en":"I can return my attention to something real even when thoughts keep coming.","ruNeutral":"Мне не нужно побеждать отвлечение. Можно заметить один предмет.","enNeutral":"I do not need to defeat distraction. I can notice one object."},{"ru":"Разным дням нужна разная поддержка: иногда пауза, иногда уменьшение требований.","en":"Different days may call for different support: sometimes rest, sometimes fewer demands.","ruNeutral":"Если непонятно, что мне нужно, можно выбрать нейтральную паузу.","enNeutral":"If I am unsure what I need, I can choose a neutral pause."},{"ru":"Чувство может быть рядом со мной, но оно не обязано управлять каждым моим шагом.","en":"A feeling can be present without deciding every step I take.","ruNeutral":"Можно назвать чувство персонажа или просто посмотреть на предмет.","enNeutral":"I can name a character's feeling or simply look at an object."},{"ru":"Я могу заметить тревожную мысль и всё-таки сделать небольшой выбор по своим ценностям.","en":"I can notice a worrying thought and still take a small values-based step.","ruNeutral":"Даже если мысль не исчезла, можно отложить решение или сделать паузу.","enNeutral":"Even if the thought stays, I can postpone a decision or pause."},{"ru":"Я могу повторить свою границу спокойно, даже если меня попросили ещё раз.","en":"I can restate a boundary calmly if someone asks again.","ruNeutral":"Можно мысленно прочитать фразу, не вступая в реальный разговор.","enNeutral":"I can read the phrase silently without having a real conversation."},{"ru":"Мне не нужно применять всё сразу: один подходящий шаг и запасной вариант уже полезны.","en":"I do not need to use every skill at once; one suitable step and a backup may be enough.","ruNeutral":"Мой план может быть простым, а неизвестное можно оставить неизвестным.","enNeutral":"My plan can stay simple; I can leave some things undecided."}])
const EN_CASES=Object.freeze([{"example":"During one task, four new messages arrive. The event is four messages; the first possible signal is starting to hurry.","case":"Just before leaving, someone asks you to do one more thing. What could help you notice stress early?","choices":["Notice the first sign of hurry and consider postponing a non-urgent task","Assume any hurry always means danger","Force yourself to finish everything immediately"],"hint":"The event and the first change in your attention are different things.","note":"Early noticing may leave room for a small choice. Rest or asking for time can also be appropriate."},{"example":"A person waiting for an email chooses the edge of a window and the shape of a cup as ordinary visual anchors.","case":"You are waiting in a queue. What could you notice without trying to force yourself to calm down?","choices":["The colour or shape of an ordinary object","A frightening imaginary possibility","A rule that every thought must stop"],"hint":"Look for a detail you can see, such as the shape of a door.","note":"A neutral visible detail is one possible anchor. You do not need to feel different immediately."},{"example":"After sitting at a laptop, a person gently changes their hand position and rests; looking at an object is equally valid.","case":"You have been sitting for a while. Which gentle option might suit you?","choices":["Change position gently, look at an object or rest","Force a painful stretch","Keep going even if movement hurts"],"hint":"The most suitable action is one you can choose without pain.","note":"Rest is a valid choice. No particular body sensation is required."},{"example":"A meeting moves to a later time. A fictional character may feel disappointment, relief or uncertainty, then choose a pause.","case":"A bus is delayed and a plan changes. How could the character respond with kindness?","choices":["Name a possible mild feeling and choose support","Blame themselves for having a feeling","Try to suppress the feeling by force"],"hint":"Different people can feel different things in the same situation.","note":"A gentle feeling can be named without needing to disappear."},{"example":"A reply has not arrived. 'There is no reply yet' is a fact; 'They dislike me' is an unconfirmed interpretation.","case":"A colleague sends a short reply. How could you respond without jumping to a conclusion?","choices":["Separate the reply from a guess about its meaning","Assume a short reply proves rejection","Force a positive thought you do not believe"],"hint":"Ask: what do I actually know from what I can observe?","note":"You may name a thought as a thought without debating or obeying it."},{"example":"A colleague asks for another task. The character says, 'I cannot do that today. I can answer tomorrow.'","case":"Someone invites you when you have no free time. Which answer sets a respectful boundary?","choices":["Thank you; I cannot today","Say yes out of fear even if it feels unsafe","Insult the person for asking"],"hint":"One short, respectful sentence can be enough.","note":"This is a fictional rehearsal; there is no requirement to confront anyone."},{"example":"After a busy day, a character notices tiredness, chooses a break and keeps a backup option of asking for time.","case":"A new household request arrives after a full day. Which plan is realistic?","choices":["Choose one familiar support and a backup","Use all seven skills even if exhausted","Treat a lack of relief as failure"],"hint":"A short sequence can be: notice → one support → rest if needed.","note":"A single workable step and a backup are enough for an educational plan."},{"example":"While replying to a customer, three notifications arrive. The character notices their attention shifting and finishes one task first.","case":"A new request appears just before you leave. What might be an early signal and a kind next step?","choices":["Notice the first rush and adjust one small demand","Promise to complete everything right away","Assume the first sign always means danger"],"hint":"Look for the very first change in pace or attention, not the strongest feeling.","note":"Revisiting a familiar skill in a new context is practice, not an exam."},{"example":"Waiting for an answer, a character looks at a window frame and the edge of a desk, without trying to silence thoughts.","case":"You are waiting at a shop. Which external detail could you choose by yourself?","choices":["A shelf edge or ordinary object","An imagined catastrophe","An effort to block every thought"],"hint":"One visible shape is enough; two objects are optional.","note":"You can choose a visual anchor while your thoughts continue."},{"example":"One person has too many tasks and reduces a demand; another is tired after work and chooses rest.","case":"One more task appears at the end of your day. What is a gentle option?","choices":["Reduce non-urgent demands, rest or ask for help","Force yourself through discomfort","Ban yourself from resting"],"hint":"Many demands and low energy may call for different supports.","note":"You do not need to diagnose your nervous system to choose a pause."},{"example":"Plans move by half an hour. A character names possible disappointment, notices a nearby object and takes a pause.","case":"A bus is late. How could the character stay kind toward their own mild frustration?","choices":["Name the possible feeling and choose a manageable step","Blame themselves for the emotion","Force themselves to feel happy"],"hint":"You may use only the fictional story if personal feelings are uncomfortable.","note":"An emotion need not disappear for you to choose a gentle response."},{"example":"A colleague replies 'OK'. The character notices a worry, names the known fact and chooses clarity as a value.","case":"Someone has not confirmed an invitation. What is a respectful next step?","choices":["Separate fact from guess, and act gently according to a value","Take silence as proof of rejection","Force an optimistic belief"],"hint":"The fact is simply that a reply has not yet arrived.","note":"Respectful action could be to wait, rest or ask later."},{"example":"A person says, 'I cannot today.' If asked again, they calmly repeat the boundary without giving a long defence.","case":"An invitation is repeated despite your first decline. What could be a respectful response?","choices":["Briefly repeat the boundary or end the conversation","Agree despite feeling unsafe","Insult the person"],"hint":"A short phrase can be sufficient; this is only a fictional rehearsal.","note":"Safety matters more than asserting a boundary in a real-world confrontation."},{"example":"A small task appears at the end of the day. A person notices tiredness, reduces a demand and keeps rest as backup.","case":"Your plans change unexpectedly. What support might really be available to you?","choices":["Choose one familiar skill and a backup","Use every technique at once","Call the day a failure if nothing changes"],"hint":"Try notice → one support → a small step → a backup.","note":"The plan should use only supports you actually find available."}])
const RU_LABELS=Object.freeze(['Начинаем','Мой настрой сейчас','Выбираю темп','Фокус дня','Мысль дня','Один понятный пример','Как мне удобнее','Учусь замечать','Пробую сделать','Повторяю по желанию','Новая ситуация','Мой маленький план','Что мне подошло','Сохранить мой опыт'])
const EN_LABELS=Object.freeze(['Let’s begin','My state right now','Choose your pace','Today’s focus','One thought for today','A simple example','Prepare gently','Notice one detail','Try one small step','Repeat if you wish','A new everyday example','My small plan','What suited me?','Save my experience'])

const permitted=Object.freeze({
 welcome:['steady','tense','low','unsure'],
 baseline:[],
 pace:['standard','quick','read'],
 focus:['fits','general','unsure'],
 aphorism:['agree','unsure','disagree'],
 demo:['clear','example','difficult'],
 prepare:['try','simple','read'],
 notice:['tried','partly','not_yet','not_attempted','uncomfortable'],
 act:['tried','partly','not_yet','not_attempted','uncomfortable'],
 rehearse:['independent','guided','partly','not_yet','not_attempted','uncomfortable'],
 scenario:['one','two','three'],
 transfer:['planned','imagined','not_planning'],
 reflection:['useful','partly','unchanged','uncomfortable'],
 save:[],
})
export const OPORA54_ANSWER_OPTIONS=permitted
export const OPORA54_HINT_KEYS=Object.freeze(['demo','notice','act','rehearse','scenario'])
const HINT_SET=new Set(OPORA54_HINT_KEYS)

function numberedSteps(text){
  return String(text||'').split(/(?=\b[1-9]\.\s)/)
    .map(p=>p.replace(/^\s*[1-9]\.\s*/,'').trim()).filter(Boolean)
}

export function opora54Day(day,locale='en'){
  if(!Number.isInteger(day)||day<1||day>14)return null
  const index=day-1,ru=locale==='ru'
  const source=oporaSkillForDay(day,ru?'ru':'en')
  const quote=QUOTES[index]
  const fresh=EN_CASES[index]
  const steps=numberedSteps(source.guide)
  const english=[
    `Day ${day} of 14. Today: ${source.title}. You can begin exactly as you are.`,
    `If you wish, how available does this skill feel right now? Choose 0–10, or continue without a rating.`,
    'Choose a gentle pace. You may use the ordinary version, a shorter version or read only. You can stop at any time.',
    `Today we practise: ${source.teaching} An ordinary, general focus is enough.`,
    `A thought for today: “${quote.en}” What do you think? You do not have to agree.`,
    `First, watch a small everyday example. ${fresh.example}`,
    'You may use a fictional situation, an ordinary object around you, or simply read. Keep your breathing natural and your eyes open if you prefer.',
    `First, just notice. ${steps[0]||fresh.hint} No change in how you feel is required.`,
    `Try one small step now, if comfortable. ${steps[1]||steps[0]||fresh.hint} You may use a simpler option.`,
    `Now repeat in a way that suits you. ${steps[2]||steps[1]||fresh.hint} A hint is always available; there is no test.`,
    `Here is a new gentle situation. ${fresh.case}`,
    `Where might you use this, if you wish? ${source.transfer} A plan is not an obligation.`,
    `How did that feel for you? ${source.reflection} There may be no change, and that is fine.`,
    `Your learning card: ${source.outcome} Only the answers you chose will be saved after confirmation.`,
  ]
  const screens=(ru?RU[index].slice(0,14):english)
    .map((text,i)=>Object.freeze({
      key:OPORA54_PRE_SAVE_KEYS[i],kind:OPORA54_PRE_SAVE_KEYS[i],
      title:(ru?RU_LABELS:EN_LABELS)[i],text,
    }))
  return Object.freeze({
    day,week:day>7?2:1,skillId:source.skillId,skill:source.skill,
    title:source.title,teaching:source.teaching,guide:source.guide,
    outcome:source.outcome,quote:ru?quote.ru:quote.en,
    neutralQuote:ru?quote.ruNeutral:quote.enNeutral,
    neutral:source.neutral,reflection:source.reflection,transfer:source.transfer,
    practiceSeconds:350,durationSeconds:650,practiceMode:source.practiceMode,
    slideModel:OPORA54_SLIDE_MODEL,scales:source.scales,
    hint:ru?(RU[index][5]?.slice(0,180)||source.neutral):fresh.hint,
    scenario:Object.freeze({prompt:ru?RU[index][10]:fresh.case,
      choices:ru?[
        'Выбрать мягкий, посильный ответ из знакомых способов',
        'Сделать всё быстрее любой ценой',
        'Обязательно добиться немедленного облегчения',
      ]:fresh.choices,
      explanation:ru?source.neutral:fresh.note}),
    screens:Object.freeze(screens),
  })
}

export function opora54SkillCards(locale='en'){return oporaSkillCards(locale)}
// Save only bounded enums. Missing answers are null/not submitted, never 'skip'.
export function validateOpora54Signals(input){
  if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('INVALID_OPORA54_SIGNALS')
  if(Object.keys(input).some(k=>!['answers','hints','ease'].includes(k)))throw new Error('INVALID_OPORA54_SIGNAL_FIELD')
  const answers=input.answers??{}
  if(!answers||typeof answers!=='object'||Array.isArray(answers))throw new Error('INVALID_OPORA54_ANSWERS')
  const keys=Object.keys(answers)
  if(keys.length>OPORA54_PRE_SAVE_KEYS.length)throw new Error('INVALID_OPORA54_ANSWERS')
  const result={}
  for(const key of keys){
    if(!Object.hasOwn(permitted,key)||!permitted[key].includes(answers[key]))
      throw new Error('INVALID_OPORA54_ANSWER')
    result[key]=answers[key]
  }
  const hints=input.hints??[]
  if(!Array.isArray(hints)||hints.length>OPORA54_HINT_KEYS.length||
    hints.some(s=>typeof s!=='string'||!HINT_SET.has(s))||new Set(hints).size!==hints.length)
    throw new Error('INVALID_OPORA54_HINTS')
  const ease=input.ease??null
  if(ease!==null&&(!Number.isInteger(ease)||ease<0||ease>3))throw new Error('INVALID_OPORA54_EASE')
  return {answers:result,hints:[...hints],ease}
}
export function opora54BlueprintValid(){
  return RU.length===14&&QUOTES.length===14&&EN_CASES.length===14&&
    Array.from({length:14},(_,i)=>i+1).every(day=>['ru','en'].every(lang=>{
      const v=opora54Day(day,lang)
      return v?.screens.length===14&&v.screens.every((x,i)=>x.key===OPORA54_PRE_SAVE_KEYS[i]&&x.text.length>35)&&
        v.quote.length>20&&v.scenario.choices.length===3
    }))
}
